// Extract LLM response safely
const raw = $input.item.json;
const queryData = $node['Parse Query & Context'].json;

let answer = '';
try {
  answer = raw.choices?.[0]?.message?.content || '';
} catch (e) {
  answer = queryData.lang === 'fr'
    ? 'Desole, une erreur est survenue. Veuillez reessayer.'
    : 'Sorry, an error occurred. Please try again.';
}

return {
  status: 'SUCCESS',
  response: answer.trim(),
  query: queryData.query,
  lang: queryData.lang,
  session_id: queryData.sessionId,
  model: raw.model || 'trinity',
  tokens_used: raw.usage?.total_tokens || 0,
  timestamp: new Date().toISOString(),
  engine: 'PROJECT_CHATBOT'
};
